// MnageEvents.js
import React, { useState } from "react";
import { FaSearch, FaEdit, FaTrash, FaFilter, FaCog } from "react-icons/fa";
import SidebarLayout from "./SidebarLayout";
import img1 from "../../assets/charity_walk.png";
import img2 from "../../assets/cook-off.png";
import img3 from "../../assets/talent.png";
import CustomTable from "../";

const events = [
  {
    title: "Sports day",
    description:
      "Celebrate Sports Day on June 15 in Seychelles with exciting games, teamwork, and community",
    date: "June 15, 2025",
    status: "completed",
    type: "Youth",
    image: img1,
  },
  {
    title: "Sports day",
    description:
      "Celebrate Sports Day on June 15 in Seychelles with exciting games, teamwork, and community",
    date: "June 15, 2025",
    status: "completed",
    type: "Events",
    image: img1,
  },
  {
    title: "Navratri",
    description:
      "Celebrate Navratri with vibrant dances, devotion, and cultural unity honoring the divine feminine.",
    date: "June 25, 2025",
    status: "completed",
    type: "Cultural",
    image: img2,
  },
  {
    title: "Navratri",
    description:
      "Celebrate Navratri with vibrant dances, devotion, and cultural unity honoring the divine feminine.",
    date: "June 25, 2025",
    status: "completed",
    type: "Com_service",
    image: img2,
  },
  {
    title: "Event heading",
    description: "event description. Maximum 2 lines.",
    date: "June 25, 2025",
    status: "ongoing",
    type: "other",
    image: img3,
  },
];

const ManageEvents = () => {
  const [Events] = useState(events);
  const [searchTerm, setSearchTerm] = useState("");
  const [visibleColumns, setVisibleColumns] = useState({
    title: true,
    date: true,
    type: true,
    status: true,
  });
  const [showSettings, setShowSettings] = useState(false);

  const filteredEvents = Events.filter((event) =>
    event.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <SidebarLayout>
      <div className="w-full bg-[#FDF8F3] p-6">
        <div className="flex justify-between items-center mb-6">
          <h1 className="text-2xl font-semibold">Event Management</h1>
          <button className="bg-[#F48F0F] text-white px-4 py-2 rounded-full hover:opacity-90">
            Schedule a new event
          </button>
        </div>

        {/* Search + Icons */}
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 mb-4 relative">
          {/* Search Input */}
          <div className="flex items-center bg-white rounded-full px-4 py-2 w-full sm:max-w-md border border-gray-300">
            <FaSearch className="text-gray-400 mr-2" />
            <input
              type="text"
              placeholder="Search by Event Name"
              className="outline-none w-full text-sm"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>

          {/* Icons */}
          <div className="flex items-center gap-4 self-end sm:self-auto">
            <FaFilter className="text-[#F48F0F] cursor-pointer text-xl" />
            <div className="relative">
              <FaCog
                className="text-[#F48F0F] cursor-pointer text-xl"
                onClick={() => setShowSettings(!showSettings)}
              />
              {/* Settings dropdown */}
              {showSettings && (
                <div className="absolute top-12 right-0 bg-white shadow-lg rounded-md p-4 z-10 border border-gray-200">
                  {Object.keys(visibleColumns).map((col) => (
                    <label key={col} className="block text-sm mb-2">
                      <input
                        type="checkbox"
                        checked={visibleColumns[col]}
                        onChange={() =>
                          setVisibleColumns({
                            ...visibleColumns,
                            [col]: !visibleColumns[col],
                          })
                        }
                        className="mr-2"
                      />
                      Show {col.charAt(0).toUpperCase() + col.slice(1)}
                    </label>
                  ))}
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Table */}
        <CustomTable
          cols={[
            {
              key: "title",
              label: "Event Name",
            },
            {
              key: "date",
              label: "Date",
            },
            {
              key: "type",
              label: "Category",
            },
            {
              key: "status",
              label: "Status",
              render: (value) => (
                <span
                  className={`px-3 py-1 text-xs font-semibold rounded-full ${
                    value === "Upcoming"
                      ? "bg-green-200 text-green-800"
                      : value === "Past"
                      ? "bg-red-200 text-red-800"
                      : "bg-yellow-200 text-yellow-800"
                  }`}
                >
                  {value}
                </span>
              ),
            },
          ]}
          rows={filteredEvents.map((event) => ({
            ...event,
            actions: (
              <>
                <FaEdit className="text-[#F48F0F] cursor-pointer" />
                <FaTrash className="text-[#F48F0F] cursor-pointer" />
              </>
            ),
          }))}
          visibleCols={visibleColumns}
        />
      </div>
    </SidebarLayout>
  );
};

export default ManageEvents;
